pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log));
        amount = bound(amount, 0, 10 ether);
        unlockTime = bound(unlockTime, 0, 2 days) + block.timestamp;

        uint256 before = log.History(0) == log.History(0) ? log.getHistoryLength() : 0;
        before = log.getHistoryLength();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        uint256 afterLen = log.getHistoryLength();
        assertTrue(afterLen == before + 1, "each Put must append exactly one log entry");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1000 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: any successful Put is recorded in the log with the
        // depositor's address, the deposited value and the current timestamp.
        bool recorded;
        if (ok) {
            try log.History(0) returns (address sender, string memory, uint256 val, uint256 tim) {
                recorded = (sender == actor) && (val == amount) && (tim == block.timestamp);
            } catch {
                recorded = false;
            }
        } else {
            recorded = true; // rule only concerns successful Puts
        }
        assertTrue(recorded);
    }
}

