pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // A second independent Put from another actor must also succeed:
        // the lock is released after every completed call in the reference.
        address actor2 = address(uint160(uint160(actor) ^ 1));
        vm.deal(actor2, amount);
        bool ok;
        vm.prank(actor2);
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(msg.value == amount);
        require(amount == c.MinSum());

        // Fund the holder so its balance is exactly MinSum.
        c.Put{value: amount}(0);

        (, uint bal1) = c.Acc(address(this));
        require(bal1 == amount);

        // Time must have advanced past the recorded unlock time.
        (uint ut, ) = c.Acc(address(this));
        require(block.timestamp > ut);

        // In P this succeeds (balance >= MinSum); in M (balance > MinSum) it does nothing.
        c.Collect(amount);

        (, uint bal2) = c.Acc(address(this));
        assert(bal2 < amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

