    fallback() external payable {}
}

contract InvMutTest {
    C c;
    bool reenter;
    bool done;
    uint amount;

    constructor(C _c) { c = _c; }

    function f(uint amt, uint am, uint ut) public {
        require(2 * am <= amt);
        require(amt >= 1 ether);
        require(address(this).balance >= amt);
        reenter = true;
        done = false;
        amount = am;
        c.Put{value: amt}(ut);
        c.Collect(am);
        assert(c.Acc(address(this)).balance == amt);
    }

    receive() external payable {
        if (reenter && !done) {
            done = true;
            c.Collect(amount);
        }
    }
}

