contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a) public payable {
        require(a >= 1 && msg.value >= 1 ether + a);
        // Deposit from this test contract itself, so this account has balance.
        c.Put(0){value: msg.value}();
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        (uint ut, uint bal) = c.Acc(address(this));
        assert(!reverted && bal == msg.value - a && ut <= block.timestamp);
    }
    receive() external payable { }
